<?php
declare(strict_types=1);

date_default_timezone_set('Asia/Manila');

function db(): PDO {
    static $pdo = null;
    if ($pdo instanceof PDO) return $pdo;
    $dir = __DIR__ . '/data';
    if (!is_dir($dir)) mkdir($dir, 0775, true);
    $pdo = new PDO('sqlite:' . $dir . '/foodtraps.sqlite', null, null, [PDO::ATTR_ERRMODE => PDO::ERRMODE_EXCEPTION, PDO::ATTR_DEFAULT_FETCH_MODE => PDO::FETCH_ASSOC]);
    $pdo->exec('PRAGMA foreign_keys = ON');
    $pdo->exec("CREATE TABLE IF NOT EXISTS menu (id TEXT PRIMARY KEY, category TEXT NOT NULL, name TEXT NOT NULL, price REAL NOT NULL DEFAULT 0, available INTEGER NOT NULL DEFAULT 1, image TEXT NOT NULL DEFAULT '')");
    $menuColumns = array_column($pdo->query('PRAGMA table_info(menu)')->fetchAll(), 'name');
    if (!in_array('points_enabled', $menuColumns, true)) $pdo->exec("ALTER TABLE menu ADD COLUMN points_enabled INTEGER NOT NULL DEFAULT 0");
    if (!in_array('points_per_item', $menuColumns, true)) $pdo->exec("ALTER TABLE menu ADD COLUMN points_per_item INTEGER NOT NULL DEFAULT 0");
    if (!in_array('points_expires_on', $menuColumns, true)) $pdo->exec("ALTER TABLE menu ADD COLUMN points_expires_on TEXT NOT NULL DEFAULT ''");
    if (!in_array('redeem_enabled', $menuColumns, true)) $pdo->exec("ALTER TABLE menu ADD COLUMN redeem_enabled INTEGER NOT NULL DEFAULT 0");
    if (!in_array('privilege_discount_eligible', $menuColumns, true)) $pdo->exec("ALTER TABLE menu ADD COLUMN privilege_discount_eligible INTEGER NOT NULL DEFAULT 0");
    $pdo->exec("CREATE TABLE IF NOT EXISTS orders (order_number TEXT PRIMARY KEY, date TEXT NOT NULL, time TEXT NOT NULL, customer_name TEXT NOT NULL, contact_number TEXT NOT NULL, order_type TEXT NOT NULL, delivery_address TEXT NOT NULL DEFAULT '', special_instructions TEXT NOT NULL DEFAULT '', cashier TEXT NOT NULL DEFAULT '', subtotal REAL NOT NULL, discount REAL NOT NULL, delivery_fee REAL NOT NULL, total REAL NOT NULL, payment_method TEXT NOT NULL, amount_received REAL NOT NULL DEFAULT 0, change_due REAL NOT NULL DEFAULT 0, status TEXT NOT NULL, suki_card_number TEXT NOT NULL DEFAULT '', suki_points_awarded INTEGER NOT NULL DEFAULT 0)");
    $orderColumns = array_column($pdo->query('PRAGMA table_info(orders)')->fetchAll(), 'name');
    if (!in_array('vat_amount', $orderColumns, true)) $pdo->exec("ALTER TABLE orders ADD COLUMN vat_amount REAL NOT NULL DEFAULT 0");
    if (!in_array('discount_type', $orderColumns, true)) $pdo->exec("ALTER TABLE orders ADD COLUMN discount_type TEXT NOT NULL DEFAULT 'None'");
    if (!in_array('privilege_id_type', $orderColumns, true)) $pdo->exec("ALTER TABLE orders ADD COLUMN privilege_id_type TEXT NOT NULL DEFAULT ''");
    if (!in_array('privilege_id_number', $orderColumns, true)) $pdo->exec("ALTER TABLE orders ADD COLUMN privilege_id_number TEXT NOT NULL DEFAULT ''");
    if (!in_array('special_instructions', $orderColumns, true)) $pdo->exec("ALTER TABLE orders ADD COLUMN special_instructions TEXT NOT NULL DEFAULT ''");
    if (!in_array('cancellation_reason', $orderColumns, true)) $pdo->exec("ALTER TABLE orders ADD COLUMN cancellation_reason TEXT NOT NULL DEFAULT ''");
    if (!in_array('rider_username', $orderColumns, true)) $pdo->exec("ALTER TABLE orders ADD COLUMN rider_username TEXT NOT NULL DEFAULT ''");
    if (!in_array('packaging_type', $orderColumns, true)) $pdo->exec("ALTER TABLE orders ADD COLUMN packaging_type TEXT NOT NULL DEFAULT ''");
    if (!in_array('packaging_fee', $orderColumns, true)) $pdo->exec("ALTER TABLE orders ADD COLUMN packaging_fee REAL NOT NULL DEFAULT 0");
    if (!in_array('packaging_quantity', $orderColumns, true)) $pdo->exec("ALTER TABLE orders ADD COLUMN packaging_quantity INTEGER NOT NULL DEFAULT 0");
    if (!in_array('packaging_note', $orderColumns, true)) $pdo->exec("ALTER TABLE orders ADD COLUMN packaging_note TEXT NOT NULL DEFAULT ''");
    if (!in_array('payment_reference', $orderColumns, true)) $pdo->exec("ALTER TABLE orders ADD COLUMN payment_reference TEXT NOT NULL DEFAULT ''");
    if (!in_array('suki_card_number', $orderColumns, true)) $pdo->exec("ALTER TABLE orders ADD COLUMN suki_card_number TEXT NOT NULL DEFAULT ''");
    if (!in_array('suki_points_awarded', $orderColumns, true)) $pdo->exec("ALTER TABLE orders ADD COLUMN suki_points_awarded INTEGER NOT NULL DEFAULT 0");
    if (!in_array('suki_points_redeemed', $orderColumns, true)) $pdo->exec("ALTER TABLE orders ADD COLUMN suki_points_redeemed INTEGER NOT NULL DEFAULT 0");
    if (!in_array('suki_discount', $orderColumns, true)) $pdo->exec("ALTER TABLE orders ADD COLUMN suki_discount REAL NOT NULL DEFAULT 0");
    if (!in_array('delivery_latitude', $orderColumns, true)) $pdo->exec("ALTER TABLE orders ADD COLUMN delivery_latitude REAL");
    if (!in_array('delivery_longitude', $orderColumns, true)) $pdo->exec("ALTER TABLE orders ADD COLUMN delivery_longitude REAL");
    if (!in_array('location_accuracy', $orderColumns, true)) $pdo->exec("ALTER TABLE orders ADD COLUMN location_accuracy REAL");
    $pdo->exec("CREATE TABLE IF NOT EXISTS order_items (id INTEGER PRIMARY KEY AUTOINCREMENT, order_number TEXT NOT NULL, item_id TEXT NOT NULL, item_name TEXT NOT NULL, category TEXT NOT NULL, quantity INTEGER NOT NULL, price REAL NOT NULL, subtotal REAL NOT NULL)");
    $itemColumns = array_column($pdo->query('PRAGMA table_info(order_items)')->fetchAll(), 'name');
    if (!in_array('vat_amount', $itemColumns, true)) $pdo->exec("ALTER TABLE order_items ADD COLUMN vat_amount REAL NOT NULL DEFAULT 0");
    $pdo->exec("CREATE TABLE IF NOT EXISTS cash_drawer_entries (id INTEGER PRIMARY KEY AUTOINCREMENT, entry_date TEXT NOT NULL, entry_time TEXT NOT NULL, cashier TEXT NOT NULL, entry_type TEXT NOT NULL, amount REAL NOT NULL DEFAULT 0, notes TEXT NOT NULL DEFAULT '')");
    $pdo->exec("CREATE TABLE IF NOT EXISTS settings (key TEXT PRIMARY KEY, value TEXT NOT NULL)");
    $q=$pdo->prepare('SELECT value FROM settings WHERE key=?');$q->execute(['PUBLIC_CASH_ORDERS_PENDING_V1']);if($q->fetchColumn()===false){$pdo->exec("UPDATE orders SET amount_received=0,change_due=0 WHERE cashier='' AND upper(payment_method)='CASH' AND amount_received>=total AND upper(status) NOT IN ('CANCELLED','COMPLETED','DELIVERED','PAID')");$q=$pdo->prepare('INSERT INTO settings(key,value) VALUES(?,?)');$q->execute(['PUBLIC_CASH_ORDERS_PENDING_V1','done']);}
    $pdo->exec("CREATE TABLE IF NOT EXISTS users (username TEXT PRIMARY KEY, pin TEXT NOT NULL, role TEXT NOT NULL, active INTEGER NOT NULL DEFAULT 1)");
    $userColumns = array_column($pdo->query('PRAGMA table_info(users)')->fetchAll(), 'name');
    foreach (['full_name'=>"TEXT NOT NULL DEFAULT ''", 'contact'=>"TEXT NOT NULL DEFAULT ''", 'personal_info'=>"TEXT NOT NULL DEFAULT ''", 'position'=>"TEXT NOT NULL DEFAULT ''", 'date_hired'=>"TEXT NOT NULL DEFAULT ''", 'photo_url'=>"TEXT NOT NULL DEFAULT ''", 'staff_id'=>"TEXT NOT NULL DEFAULT ''", 'id_name_font_size'=>"INTEGER NOT NULL DEFAULT 14", 'id_back_note'=>"TEXT NOT NULL DEFAULT ''", 'emergency_contact_name'=>"TEXT NOT NULL DEFAULT ''", 'emergency_contact_number'=>"TEXT NOT NULL DEFAULT ''", 'id_position_font_size'=>"INTEGER NOT NULL DEFAULT 10", 'id_date_font_size'=>"INTEGER NOT NULL DEFAULT 10", 'id_number_font_size'=>"INTEGER NOT NULL DEFAULT 10"] as $column=>$definition) { if (!in_array($column, $userColumns, true)) $pdo->exec("ALTER TABLE users ADD COLUMN $column $definition"); }
    $pdo->exec("UPDATE users SET staff_id='FTS-'||printf('%04d',rowid) WHERE staff_id=''");
    $pdo->exec("CREATE TABLE IF NOT EXISTS riders (id TEXT PRIMARY KEY, name TEXT NOT NULL, contact TEXT NOT NULL DEFAULT '', username TEXT NOT NULL DEFAULT '', status TEXT NOT NULL DEFAULT 'AVAILABLE', active INTEGER NOT NULL DEFAULT 1)");
    $pdo->exec("CREATE TABLE IF NOT EXISTS suki_cards (card_number TEXT PRIMARY KEY, customer_name TEXT NOT NULL, contact TEXT NOT NULL UNIQUE, address TEXT NOT NULL DEFAULT '', created_at TEXT NOT NULL, points INTEGER NOT NULL DEFAULT 0, expires_on TEXT NOT NULL DEFAULT '')");
    $sukiColumns = array_column($pdo->query('PRAGMA table_info(suki_cards)')->fetchAll(), 'name');
    if (!in_array('points', $sukiColumns, true)) $pdo->exec("ALTER TABLE suki_cards ADD COLUMN points INTEGER NOT NULL DEFAULT 0");
    if (!in_array('expires_on', $sukiColumns, true)) $pdo->exec("ALTER TABLE suki_cards ADD COLUMN expires_on TEXT NOT NULL DEFAULT ''");
    if (!in_array('active', $sukiColumns, true)) $pdo->exec("ALTER TABLE suki_cards ADD COLUMN active INTEGER NOT NULL DEFAULT 1");
    $pdo->exec("CREATE TABLE IF NOT EXISTS suki_points_history (id INTEGER PRIMARY KEY AUTOINCREMENT, card_number TEXT NOT NULL, member_name TEXT NOT NULL DEFAULT '', event_type TEXT NOT NULL, points_change INTEGER NOT NULL, balance_after INTEGER, order_number TEXT NOT NULL DEFAULT '', details TEXT NOT NULL DEFAULT '', staff TEXT NOT NULL DEFAULT 'system', created_at TEXT NOT NULL, source_key TEXT UNIQUE)");
    $historyColumns = array_column($pdo->query('PRAGMA table_info(suki_points_history)')->fetchAll(), 'name');
    if (!in_array('member_name', $historyColumns, true)) $pdo->exec("ALTER TABLE suki_points_history ADD COLUMN member_name TEXT NOT NULL DEFAULT ''");
    $pdo->exec("UPDATE suki_points_history SET member_name=COALESCE((SELECT customer_name FROM suki_cards WHERE card_number=suki_points_history.card_number),'') WHERE member_name=''");
    $pdo->exec("INSERT OR IGNORE INTO suki_points_history(card_number,member_name,event_type,points_change,balance_after,order_number,details,staff,created_at,source_key) SELECT o.suki_card_number,COALESCE(c.customer_name,''),'EARNED',o.suki_points_awarded,NULL,o.order_number,'Existing points earned before history tracking began.','system',o.date||' '||o.time,'legacy-earned:'||o.order_number FROM orders o LEFT JOIN suki_cards c ON c.card_number=o.suki_card_number WHERE o.suki_card_number<>'' AND o.suki_points_awarded>0");
    if (in_array('suki_points_redeemed', $orderColumns, true)) $pdo->exec("INSERT OR IGNORE INTO suki_points_history(card_number,member_name,event_type,points_change,balance_after,order_number,details,staff,created_at,source_key) SELECT o.suki_card_number,COALESCE(c.customer_name,''),'REDEEMED',-o.suki_points_redeemed,NULL,o.order_number,'Existing redemption recorded before history tracking began.','system',o.date||' '||o.time,'legacy-redeemed:'||o.order_number FROM orders o LEFT JOIN suki_cards c ON c.card_number=o.suki_card_number WHERE o.suki_card_number<>'' AND o.suki_points_redeemed>0");
    $pdo->exec("CREATE TABLE IF NOT EXISTS audit_log (id INTEGER PRIMARY KEY AUTOINCREMENT, timestamp TEXT NOT NULL, user TEXT NOT NULL, action TEXT NOT NULL, reference TEXT NOT NULL, details TEXT NOT NULL)");
    $pdo->exec("CREATE TABLE IF NOT EXISTS rider_locations (order_number TEXT PRIMARY KEY, rider_username TEXT NOT NULL, lat REAL NOT NULL, lng REAL NOT NULL, updated_at TEXT NOT NULL)");
    $riderColumns = array_column($pdo->query('PRAGMA table_info(riders)')->fetchAll(), 'name');
    if (!in_array('username', $riderColumns, true)) $pdo->exec("ALTER TABLE riders ADD COLUMN username TEXT NOT NULL DEFAULT ''");
    foreach (['ADMIN_PIN'=>'123456','FRONTDESK_PIN'=>'111111','KITCHEN_PIN'=>'222222','RIDER_PIN'=>'333333','DELIVERY_FEE'=>'50','BUSINESS_NAME'=>'FOODTRAPS CAFÉ','TAGLINE'=>'Where Good Taste Costs No More'] as $k=>$v) {
        $q=$pdo->prepare('INSERT OR IGNORE INTO settings(key,value) VALUES(?,?)'); $q->execute([$k,$v]);
    }
    foreach ([['admin','123456','ADMIN'],['frontdesk','111111','FRONTDESK'],['kitchen','222222','KITCHEN'],['rider','333333','RIDER']] as $u) {
        $q=$pdo->prepare('INSERT OR IGNORE INTO users(username,pin,role,active) VALUES(?,?,?,1)'); $q->execute($u);
    }
    if ((int)$pdo->query('SELECT COUNT(*) FROM menu')->fetchColumn() === 0) {
        $sample = __DIR__ . '/menu.json';
        if (is_file($sample)) foreach (json_decode((string)file_get_contents($sample), true) ?: [] as $m) {
            $q=$pdo->prepare('INSERT OR IGNORE INTO menu(id,category,name,price,available,image) VALUES(?,?,?,?,?,?)'); $q->execute([$m[0],$m[1],$m[2],$m[3],!empty($m[4])?1:0,$m[5]??'']);
        }
    }
