function setting(string $key, string $fallback=''): string { $q=db()->prepare('SELECT value FROM settings WHERE key=?'); $q->execute([$key]); return (string)($q->fetchColumn() ?: $fallback); }
function recordSukiPointEvent(PDO $pdo,string $cardNumber,string $eventType,int $pointsChange,?int $balanceAfter,string $orderNumber='',string $details='',string $staff='system',?string $sourceKey=null): void { if($pointsChange===0&&$eventType!=='CARD_EVENT')return;$q=$pdo->prepare('SELECT customer_name FROM suki_cards WHERE card_number=?');$q->execute([$cardNumber]);$memberName=(string)($q->fetchColumn()?:'');$q=$pdo->prepare('INSERT OR IGNORE INTO suki_points_history(card_number,member_name,event_type,points_change,balance_after,order_number,details,staff,created_at,source_key) VALUES(?,?,?,?,?,?,?,?,?,?)');$q->execute([$cardNumber,$memberName,$eventType,$pointsChange,$balanceAfter,$orderNumber,$details,$staff,date('Y-m-d H:i:s'),$sourceKey]); }
function audit(string $user,string $action,string $ref='',string $details=''): void { $q=db()->prepare('INSERT INTO audit_log(timestamp,user,action,reference,details) VALUES(?,?,?,?,?)'); $q->execute([date('Y-m-d H:i:s'),$user?:'system',$action,$ref,$details]); }
function menuRows(bool $all=true): array { $sql='SELECT id,category,name,price,available,image,points_enabled AS pointsEnabled,points_per_item AS pointsPerItem,points_expires_on AS pointsExpiresOn,redeem_enabled AS redeemEnabled,privilege_discount_eligible AS privilegeDiscountEligible FROM menu'.($all?'':' WHERE available=1').' ORDER BY rowid'; return array_map(function($r){$r['available']=(bool)$r['available'];$r['price']=(float)$r['price'];$r['pointsEnabled']=(bool)$r['pointsEnabled'];$r['pointsPerItem']=(int)$r['pointsPerItem'];$r['pointsExpiresOn']=(string)$r['pointsExpiresOn'];$r['redeemEnabled']=(bool)$r['redeemEnabled'];$r['privilegeDiscountEligible']=(bool)$r['privilegeDiscountEligible'];return $r;},db()->query($sql)->fetchAll()); }
function orderRow(string $id): ?array { $q=db()->prepare('SELECT * FROM orders WHERE order_number=?');$q->execute([$id]);$r=$q->fetch();if(!$r)return null;return ['orderNumber'=>$r['order_number'],'date'=>$r['date'],'time'=>$r['time'],'customerName'=>$r['customer_name'],'contactNumber'=>$r['contact_number'],'orderType'=>$r['order_type'],'deliveryAddress'=>$r['delivery_address'],'deliveryLatitude'=>isset($r['delivery_latitude'])?(float)$r['delivery_latitude']:null,'deliveryLongitude'=>isset($r['delivery_longitude'])?(float)$r['delivery_longitude']:null,'locationAccuracy'=>isset($r['location_accuracy'])?(float)$r['location_accuracy']:null,'specialInstructions'=>$r['special_instructions']??'','packagingType'=>$r['packaging_type']??'','packagingNote'=>$r['packaging_note']??'','packagingQuantity'=>(int)($r['packaging_quantity']??0),'packagingFee'=>(float)($r['packaging_fee']??0),'paymentReference'=>$r['payment_reference']??'','cancellationReason'=>$r['cancellation_reason']??'','riderUsername'=>$r['rider_username']??'','cashier'=>$r['cashier'],'sukiCardNumber'=>$r['suki_card_number']??'','sukiPointsEarned'=>(int)($r['suki_points_awarded']??0),'sukiPointsRedeemed'=>(int)($r['suki_points_redeemed']??0),'sukiDiscount'=>(float)($r['suki_discount']??0),'subtotal'=>(float)$r['subtotal'],'discount'=>(float)$r['discount'],'discountType'=>$r['discount_type']??'None','privilegeIdType'=>$r['privilege_id_type']??'','privilegeIdNumber'=>$r['privilege_id_number']??'','vatAmount'=>(float)($r['vat_amount']??0),'deliveryFee'=>(float)$r['delivery_fee'],'total'=>(float)$r['total'],'paymentMethod'=>$r['payment_method'],'amountReceived'=>(float)$r['amount_received'],'change'=>(float)$r['change_due'],'status'=>$r['status']]; }
function orderItems(string $id): array { $q=db()->prepare('SELECT order_number AS orderNumber,item_id AS itemId,item_name AS itemName,category,quantity,price,subtotal,vat_amount AS vatAmount FROM order_items WHERE order_number=?');$q->execute([$id]);return $q->fetchAll(); }
function applyItemVat(array &$items,float $discountRate,float $sukiDiscount,string $discountType='None'): float { $type=strtoupper($discountType);$vatExempt=in_array($type,['SENIOR CITIZEN','PWD'],true);$bases=[];$eligibleBase=0.0;$discountTotal=0.0;foreach($items as $i=>$item){$lineRate=$type==='5% PRIVILEGE DISCOUNT'?(!empty($item['privilegeDiscountEligible'])?.05:0.0):$discountRate;$base=round((float)$item['subtotal']*(1-$lineRate),2);$bases[$i]=$base;$discountTotal+=round((float)$item['subtotal']*$lineRate,2);if(!empty($item['redeemEnabled']))$eligibleBase+=$base;}if($type==='5% PRIVILEGE DISCOUNT')$discountTotal=round($discountTotal,2);if($vatExempt){foreach($items as &$item)$item['vatAmount']=0.0;unset($item);return 0.0;}$vat=0.0;foreach($items as $i=>&$item){$sukiShare=!empty($item['redeemEnabled'])&&$eligibleBase>0?$sukiDiscount*$bases[$i]/$eligibleBase:0.0;$item['vatAmount']=round(max(0,$bases[$i]-$sukiShare)*0.12,2);$vat+=$item['vatAmount'];}unset($item);return round($vat,2); }
function allOrders(bool $withItems=false): array { $rows=db()->query('SELECT order_number FROM orders ORDER BY rowid DESC')->fetchAll();return array_map(function($r)use($withItems){$o=orderRow($r['order_number']);if($withItems)$o['items']=orderItems($r['order_number']);return $o;},$rows); }
